/**
 * BodyEventTypes - Central registry for physics body event type constants
 *
 * Provides typed constants for all physics body events. Using these constants
 * instead of hardcoded strings enables IDE autocompletion, prevents typos,
 * and makes event types discoverable.
 *
 * @module @three-blocks/pro/core/BodyEventTypes
 * @short Central body event type registry
 * @category Physics
 * @tags Events, Constants, Physics
 *
 * @example
 * ```js
 * import { BodyEvent } from '@three-blocks/pro';
 *
 * api.body.addEventListener(BodyEvent.HIT, (event) => {
 *   console.log('Hit at:', event.hitPoint);
 * });
 * ```
 */
/**
 * Emitted when body starts colliding with another body.
 * @type {string}
 * @event collide
 * @property {number} collidingBodyIndex - Index of the colliding body
 * @property {string} collidingBodyType - Type of the colliding body
 * @property {Object} point - Collision point { x, y, z }
 * @property {Object} normal - Collision normal { x, y, z }
 */
export const COLLIDE: string;
/**
 * Emitted when body stops colliding with another body.
 * @type {string}
 * @event collideEnd
 * @property {number} collidingBodyIndex - Index of the body that was colliding
 * @property {string} collidingBodyType - Type of the body that was colliding
 */
export const COLLIDE_END: string;
/**
 * Emitted when body is hit by a rayshoot (hitscan weapon).
 * @type {string}
 * @event hit
 * @property {number} shooterIndex - Index of the shooter body
 * @property {string} shooterType - Type of the shooter body
 * @property {Object} hitPoint - Hit point { x, y, z }
 * @property {Object} hitNormal - Surface normal at hit point { x, y, z }
 * @property {number} distance - Distance from shooter to hit
 * @property {number} instanceIdx - Instance index for instanced meshes (or -1)
 * @property {Object} hitUV - UV coordinates at hit point (if available)
 */
export const HIT: string;
/**
 * Emitted when a projectile explodes (on collision or timeout).
 * Dispatched globally via physics.weapons.onExplode() instead of per-body listeners.
 * @type {string}
 * @event projectileExplode
 * @property {number} projectileId - Projectile index in physics simulation
 * @property {Object} position - Explosion location { x, y, z }
 * @property {Object} velocity - Projectile velocity at detonation { x, y, z }
 * @property {number} damage - Base damage value
 * @property {number} aoeRadius - Blast radius in meters
 * @property {number} shooterIndex - Index of the shooter body
 * @property {string} shooterType - Type of the shooter body ('dynamic' or 'kinematic')
 * @property {'collision'|'timeout'} cause - What triggered the explosion
 * @property {string} [targetType] - Type of hit body (only if cause === 'collision')
 * @property {number} [targetIndex] - Index of hit body (only if cause === 'collision')
 * @property {number} timestamp - Physics frame time of explosion
 */
export const PROJECTILE_EXPLODE: string;
/**
 * Emitted when a dynamic body enters this zone trigger.
 * Only applicable to zone-type bodies.
 * @type {string}
 * @event zoneEnter
 * @property {number} bodyIndex - Index of the body that entered
 * @property {string} bodyType - Type of the body that entered
 */
export const ZONE_ENTER: string;
/**
 * Emitted when a dynamic body leaves this zone trigger.
 * Only applicable to zone-type bodies.
 * @type {string}
 * @event zoneLeave
 * @property {number} bodyIndex - Index of the body that left
 * @property {string} bodyType - Type of the body that left
 */
export const ZONE_LEAVE: string;
/**
 * Emitted when pointer ray intersects this body.
 * @type {string}
 * @event pointerIntersect
 * @property {Array<Object>} colliders - Array of intersection objects
 * @property {number} colliders[].index - Body index
 * @property {Object} colliders[].point - Intersection point { x, y, z }
 * @property {number} colliders[].distance - Distance from pointer origin
 * @property {number} [colliders[].instanceIdx] - Instance index for instanced meshes
 * @property {boolean} isClick - True if triggered by a click
 */
export const POINTER_INTERSECT: string;
/**
 * Emitted when camera ray intersects this body.
 * Used for occlusion detection and camera collision.
 * @type {string}
 * @event cameraIntersect
 * @property {Object} point - Intersection point { x, y, z }
 * @property {number} distance - Distance from camera
 */
export const CAMERA_INTERSECT: string;
export namespace BodyEvent {
    export { COLLIDE };
    export { COLLIDE_END };
    export { HIT };
    export { PROJECTILE_EXPLODE };
    export { ZONE_ENTER };
    export { ZONE_LEAVE };
    export { POINTER_INTERSECT };
    export { CAMERA_INTERSECT };
}
